examples.code:
select
  round(100.0*(t.p-t.b)/t.b,1) promo_cat_growth,
  round(100.0*(n.p-n.b)/n.b,1) control_growth,
  round(100.0*((t.p*1.0/t.b)/(n.p*1.0/n.b)-1),1) lift_pct
from (select sum(case when period='promo' then gmv end) p,
             sum(case when period='before' then gmv end) b
      from d where cat='아우터') t,
     (select sum(case when period='promo' then gmv end) p,
             sum(case when period='before' then gmv end) b
      from d where cat='니트') n;
